import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Görsele metin eklemek, fotoğrafı anlatır. Başlık, alt yazı, alıntı ya da meme; metin görseli tamamlar.</p>\n<p>İyi metin okunur ve göze çarpar. Kötü metin ise fotoğrafta kaybolur ya da görseli bozar.</p>\n<p>Bu kılavuz, yazı tipi seçimini, boyut ve renk kurallarını, kontur ile gölgeyi ve metni nereye koyacağınızı anlatıyor.</p>\n<h2 id=\"what-text-on-image-does\">Görseldeki metin ne yapar?</h2>\n<p>Metin, görsele anlam katar. Fotoğraf tek başına anlatamaz; yazı bağlamı verir.</p>\n<p>Metin, dikkat çeker. Sosyal medya akışında yazılı görsel, yazısız görselden daha çok duraklatır.</p>\n<p>Metin, markayı duyurur. Logo ve slogan, görselle birlikte yayılır.</p>\n<h2 id=\"captions-vs-watermarks\">Alt yazı, başlık ve filigran farklı işlerdir</h2>\n<p>Alt yazı, görseli açıklar. Okurun görseli anlamasına yardım eder.</p>\n<p>Başlık, dikkat çeker. Büyük ve kalın yazılır; ilk bakışta okunur.</p>\n<p>Filigran, sahipliği gösterir. Hafif ve köşede durur; koruma amaçlıdır.</p>\n<h2 id=\"fonts-explained\">Yazı tipleri: uyan tipografiyi seçmek</h2>\n<p>Sade yazı tipleri okunur. Kalın ve temiz harfler, fotoğrafta kaybolmaz.</p>\n<p>Süslü yazı tipleri zordur. El yazısı ve dekoratif tipler, küçük boyutta okunamaz.</p>\n<p>Bir görselde en fazla iki yazı tipi kullanın. Fazla tip, karmaşa yaratır.</p>\n<h2 id=\"text-size-scaling\">Metin boyutu: küçük ve büyük fotoğraflar</h2>\n<p>Metin, fotoğraf boyutuna göre ayarlanmalıdır. Küçük fotoğrafta büyük metin, görseli kapatır.</p>\n<p>Sosyal medya için metin büyük olmalıdır. Telefondan okunmalıdır; küçük yazı kaybolur.</p>\n<p>Araçta başlığı alt yazıdan belirgin biçimde büyük tutun; boyut hiyerarşisi, okurun gözünü yönlendirir.</p>\n<h2 id=\"colour-and-contrast\">Renk ve kontrast: metni okunur yapmak</h2>\n<p>Beyaz metin, koyu fotoğrafta okunur; açık fotoğrafta kaybolur. Rengi arka plana göre seçin.</p>\n<p>Kontrast, en önemli kuraldır. Metin ile arka plan arasındaki fark büyük olmalıdır.</p>\n<p>Marka rengini deneyebilirsiniz. Renk markayı duyurur; yine de okunabilirlik önceliklidir.</p>\n<h2 id=\"outline-and-shadow\">Kontur ve gölge</h2>\n<p>Kontur, metni her arka planda okunur yapar. Beyaz yazıya siyah kontur, her zeminde görünür.</p>\n<p>Gölge, metne derinlik verir. Hafif gölge, yazıyı fotoğraftan ayırır.</p>\n<p>İkisini birlikte abartmayın. Kalın kontur ve koyu gölge, metni ağır gösterir.</p>\n<h2 id=\"positioning-and-layers\">Konum ve katmanlar</h2>\n<p>Metni, fotoğrafın düz alanına koyun. Kalabalık bölge, yazıyı okunmaz yapar.</p>\n<p>Katmanlar, metni düzenlemenizi sağlar. Her metin ayrı katmandır; taşınabilir ve silinebilir.</p>\n<p>Önemli öğelerin üzerine metin koymayın. Yüzün üzerine yazı, hem yüzü hem yazıyı bozar.</p>\n<h2 id=\"rotating-text\">Etki için metni döndürmek</h2>\n<p>Hafif eğik metin, dinamik görünür. 5-10 derecelik açı, görsele enerji verir.</p>\n<p>Araçta metni çok eğmeyin; aşırı açı okunabilirliği bozar, önce okunabilirlik gelir.</p>\n<p>Araçta metni döndürmek, meme ve afişlerde işe yarar; ciddi belgelerde metni düz bırakın.</p>\n<h2 id=\"multi-line-text\">Çok satırlı alt yazılar</h2>\n<p>Araçta uzun metni birkaç satıra bölün; kısa satırlar, uzun tek satırdan çok daha kolay okunur.</p>\n<p>Satır aralığını ayarlayın. Sıkışık satırlar, metni boğar.</p>\n<p>Her satırı ayrı katman yapmayın. Tek metin kutusu, çok satırı birlikte taşır.</p>\n<h2 id=\"memes\">Meme yapmak</h2>\n<p>Araçta klasik meme yapıyorsanız metni üste ve alta yerleştirin; kalın beyaz yazıya siyah kontur ekleyin.</p>\n<p>Meme metni kısa olmalıdır. Birkaç kelime, espriyi taşır.</p>\n<p>Meme fotoğrafı sade olmalıdır. Kalabalık görsel, espriyi boğar.</p>\n<h2 id=\"quotes-and-titles\">Alıntılar, başlıklar ve sosyal grafikler</h2>\n<p>Alıntı görsellerinde metin merkezdedir. Fotoğraf arka planda, yazı ön plandadır.</p>\n<p>Başlık büyük, kaynak küçük yazılır. Hiyerarşi, okurun gözünü yönlendirir.</p>\n<p>Sosyal grafiklerde metin kısa olmalıdır. Akışta okunan yazı, birkaç saniyede anlaşılmalıdır.</p>\n<h2 id=\"annotations\">Açıklamalar ve etiketler</h2>\n<p>Açıklamalar, görseldeki öğeyi işaret eder. Ok ve çizgi, gözü hedefe götürür.</p>\n<p>Etiketler kısa olmalıdır. Birkaç kelime, öğeyi tanımlar.</p>\n<p>Eğitim görsellerinde açıklama kullanılır. Diyagram ve talimat, etiketle anlaşılır olur.</p>\n<h2 id=\"formats-and-export\">Formatlar ve dışa aktarma</h2>\n<p>Yazılı fotoğraflar için JPG uygundur. Dosya hafiftir ve her yerde görüntülenir.</p>\n<p>Saydam katmanlı görseller için PNG gerekir. JPG saydamlığı desteklemez.</p>\n<p>Dışa aktarmadan önce önizlemeyi kontrol edin. Metnin konumu ve boyutu doğru olmalıdır.</p>\n<h2 id=\"privacy-local-processing\">Gizlilik: hiçbir şey yüklemeden metin eklemek</h2>\n<p>Metin aracı tamamen tarayıcıda çalışır. Fotoğraflarınız sunucuya yüklenmez.</p>\n<p>Bu, özel fotoğraflar için önemlidir. Aile ve müşteri fotoğraflarını güvenle düzenleyebilirsiniz.</p>\n<p>Düzenleme bitince tarayıcı temizlenir. Fotoğraflarınız sizden başkasına gitmez.</p>\n<h2 id=\"common-mistakes\">Metin eklerken yaygın hatalar</h2>\n<p>En yaygın hata, düşük kontrasttır. Açık fotoğrafta beyaz yazı kaybolur.</p>\n<p>Bir başka hata, çok küçük metindir. Telefonda okunamayan yazı, işe yaramaz.</p>\n<p>Üçüncü hata, çok fazla yazı tipidir. Bir görselde iki tipten fazlası karmaşa yaratır.</p>\n<h2 id=\"text-on-product-photos\">Ürün fotoğraflarında metin</h2>\n<p>Ürün fotoğraflarında metin kısa olmalıdır. Fiyat ve indirim, birkaç kelimeyle yazılır.</p>\n<p>Metni ürünün üzerine koymayın. Ürün görünmelidir; yazı kenarda durmalıdır.</p>\n<p>Tüm ürün görsellerinde aynı stili kullanın. Tutarlılık, mağazada profesyonel görünür.</p>\n<p>Özetle: metin okunur olmalı, fotoğrafı bozmamalıdır. Adımlar için <a href=\"/tr/blog/gorsele-metin-nasil-eklenir\">Görsele metin nasıl eklenir</a> yazısına bakın; okunabilirlik için <a href=\"/tr/blog/gorsel-uzerindeki-metin-okunabilirlik-ipuclari\">görselde metin okunabilirliği ipuçları</a> yazısı yardımcı olur. Filigran için <a href=\"/tr/gorsel-filigran-ekle\">görsel filigran</a> hazırdır; araç ise <a href=\"/tr/gorsele-metin-ekle\">görsele metin ekleme</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Fotoğraftaki metin için en iyi yazı tipi hangisi?","answer":"Sade ve kalın yazı tipleri en iyisidir; fotoğrafta kaybolmazlar. Süslü ve el yazısı tipler küçük boyutta okunamaz. Bir görselde en fazla iki yazı tipi kullanın; başlık için kalın, alt yazı için sade tip seçin."},{"question":"Parlak bir fotoğrafta beyaz metni nasıl okunur yaparım?","answer":"Kontur ya da gölge ekleyin. Beyaz yazıya siyah kontur, her zeminde görünür. Alternatif olarak metnin arkasına yarı saydam koyu panel koyun. Ya da metni fotoğrafın koyu alanına taşıyın."},{"question":"Bir görsele birden fazla metin satırı ekleyebilir miyim?","answer":"Evet. Tek metin kutusu, çok satırı birlikte taşır; Enter ile satır ekleyin. Uzun metni kısa satırlara bölün; kısa satırlar kolay okunur. Her satırı ayrı katman yapmayın."},{"question":"Metin eklemek ile filigran koymak arasındaki fark nedir?","answer":"Metin, görseli açıklar ya da dikkat çeker; büyük ve okunur yazılır. Filigran, sahipliği gösterir; hafif ve köşede durur. İkisi farklı işlerdir; metin içerik, filigran korumadır."},{"question":"Sosyal medya görselinde metin ne kadar büyük olmalı?","answer":"Telefondan okunacak kadar büyük olmalıdır. Başlık, görsel genişliğinin yüzde 10-15'i kadar olabilir. Küçük yazı akışta kaybolur; önizlemede telefon boyutunda kontrol edin."},{"question":"Fotoğrafa metin eklemek konum verilerini siler mi?","answer":"Hayır, metin eklemek EXIF verilerini silmez; konum bilgisi dosyada kalır. Konumu silmek istiyorsanız meta veri kaldırma aracını kullanın. Paylaşmadan önce konum verisini kontrol edin."}];
